using T=ks::ParameterUploadService;
namespace {bool tracking=false;uint64_t allocations=0,calls=0,phases=0,rejections=0,guards=0;}
void*operator new(std::size_t n){if(tracking)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](std::size_t n){return::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,std::size_t)noexcept{std::free(p);}void operator delete[](void*p,std::size_t)noexcept{std::free(p);}
void check(bool ok,const char*m){if(!ok)throw std::logic_error(m);}int history(uint32_t a){return a<0x400000||(a>=0xfffd10&&a<0xffffa0)?int(a):-1;}
struct Bus{uint8_t*memory;uint64_t clock=1000,hash=1469598103934665603ull,events=0;int previous=-1,lastread=-1;bool invalidAccess=false;unsigned statusReads=0,hold=0,words=0,target=0;std::array<uint32_t,100>payload{};uint32_t packet=0;
 void record(bool write,uint32_t a,uint8_t v,unsigned dt){if(!T::dataSpan(a,1)&&!(a>=0x400000&&a<0x400010)&&!(a>=0x600000&&a<0x600010)&&a!=0xffff61&&a!=0xffff62)invalidAccess=true;check(!invalidAccess,"Pure graph accessed unsupported resource");check(dt&&dt<=100,"Resource outside phase");for(uint64_t n:{uint64_t(write),uint64_t(a),uint64_t(v),clock+dt}){hash=(hash^n)*1099511628211ull;}++events;}
 uint8_t read(uint32_t a,unsigned dt){const bool status=a==0x400004||a==0x600004;const auto v=uint8_t(status?(words==target&&statusReads++<hold?0:255):memory[a]);record(false,a,v,dt);lastread=history(a);return v;}
 void write(uint32_t a,uint8_t v,unsigned dt){record(true,a,v,dt);memory[a]=v;previous=history(a);if(a==0x40000a||a==0x60000a)packet=uint32_t(v)<<16;else if(a==0x40000c||a==0x60000c)packet|=uint32_t(v)<<8;else if(a==0x40000e||a==0x60000e){check(words<payload.size(),"Too many parameter words");payload[words++]=packet|v;}}
 void advance(T&t,unsigned budget){const auto cost=t.nextClocks(previous);const auto used=t.advanceBefore(budget,[&](uint32_t a,unsigned dt){return read(a,dt);},[&](uint32_t a,uint8_t v,unsigned dt){write(a,v,dt);},previous);check(used==cost,"Pure admitted cost differs");clock+=used;if(t.effect().read)lastread=-1;if(t.effect().write)previous=-1;}
};
void seed(uint8_t*m,unsigned x,uint32_t patch){std::fill(m,m+(1u<<24),uint8_t(0));const auto byte=[&](uint32_t a,uint8_t v){m[a&0xffffff]=v;};const auto word=[&](uint32_t a,uint16_t v){byte(a,uint8_t(v>>8));byte(a+1,uint8_t(v));};const auto wide=[&](uint32_t a,uint32_t v){for(unsigned n=0;n<4;++n)byte(a+n,uint8_t(v>>(24-8*n)));};for(unsigned n=0;n<256;++n){byte(patch+n,uint8_t(x?n*x+x:0));wide(0x17560+20*n,0x1a000);for(unsigned k=4;k<20;++k)byte(0x17560+20*n+k,uint8_t(n+k+x));byte(0x1a000+n,uint8_t(63+n));}for(unsigned n=0;n<256;++n)word(0x15200+2*n,uint16_t(n*127));for(unsigned n=0;n<7;++n)word(0x15130+2*n,uint16_t(x?0x1000+x*31:0));byte(0x174a7,uint8_t(x*17));byte(0x17526,uint8_t(x&3));byte(0x167ba,uint8_t(x&1));byte(0x16798,uint8_t(x&3));byte(0x167a3,uint8_t(x&1));byte(0xffff62,255);}
int main(){try{auto first=std::make_unique<uint8_t[]>(1u<<24),second=std::make_unique<uint8_t[]>(1u<<24);uint32_t groups=0,components=0;
 const auto run=[&](unsigned x,ks::DspPort port,unsigned hold=0,unsigned target=0,uint32_t patch=0x19000){seed(first.get(),x,patch);std::copy(first.get(),first.get()+(1u<<24),second.get());T a({patch,port,0x1234}),b({patch,port,0x1234});Bus ba{first.get()},bb{second.get()};ba.hold=bb.hold=hold;ba.target=bb.target=target;tracking=true;while(!a.complete()){const auto cost=a.nextClocks(ba.previous);check(cost,"Pure upload stalled");for(unsigned budget:{0u,cost-1}){const auto before=a.summary().phases,events=ba.events;const auto used=a.advanceBefore(budget,[&](uint32_t ad,unsigned dt){return ba.read(ad,dt);},[&](uint32_t ad,uint8_t v,unsigned dt){ba.write(ad,v,dt);},ba.previous);check(!used&&a.summary().phases==before&&ba.events==events&&a.nextClocks(ba.previous)==cost,"Rejected budget changed task");++rejections;}ba.advance(a,cost);bb.advance(b,0xffffffffu);check(ba.hash==bb.hash&&ba.clock==bb.clock&&ba.events==bb.events&&ba.previous==bb.previous&&ba.lastread==bb.lastread&&a.complete()==b.complete()&&a.step()==b.step()&&a.component()==b.component(),"One-phase and excess budget traces differ");++phases;}tracking=false;check(!a.nextClocks()&&!b.nextClocks(),"Complete graph schedules work");check(ba.words==100&&bb.words==100&&a.summary().words==100,"Full image must emit100words");check(a.summary().glide&&a.summary().coefficient.observed&&a.summary().voiceObserved,"Required semantic results missing");check(a.summary().port==ks::DspPort::B&&a.summary().cachedAddress==0xffff,"Exit selectors incomplete");check(ba.payload==bb.payload&&std::equal(first.get(),first.get()+(1u<<24),second.get()),"Excess budget changed payload/memory");if(!x){check(ba.payload[0]==0x67&&ba.payload[1]==6,"Header words differ");check(ba.payload[96]==0xd10000&&ba.payload[97]==0&&ba.payload[98]==0x7fffff&&ba.payload[99]==0x910000,"Absolute glide packet differs");check(first[0x17567]==64&&first[0x1752d]==205,"Detune distance/previous publication differs");}if(hold)check(ba.statusReads>hold&&ba.statusReads==bb.statusReads,"Busy DSP failed progress");groups|=a.summary().groups;components|=a.components();++calls;};
 for(unsigned x=0;x<256;++x)for(auto port:{ks::DspPort::A,ks::DspPort::B})run(x,port);
 for(unsigned hold:{1u,3u,65537u,131074u})for(unsigned target:{0u,50u,99u})run(9,ks::DspPort::B,hold,target);
 for(uint32_t p:{0xb8e9u,0x1fff00u,0x800000u,0x81fd00u,0x8fff00u,0xc181fd01u,0xa0b8e9u,0xbfff00u,0xffdc01u,0xffef00u,0xc1019001u})run(7,ks::DspPort::A,0,0,p);
 for(uint32_t p:{0u,0xb8e7u,0x1fff01u,0x200000u,0x7fffffu,0x8fff01u,0x900000u,0xa0b8e7u,0xbfff01u,0xc00000u,0xffdbffu,0xffef01u,0xffefffu,0xfff000u,0xfff400u,0xfff800u,0xfffc00u,0xffffffffu}){bool rejected=false;try{T invalid({p,ks::DspPort::A,0});}catch(const std::logic_error&){rejected=true;}check(rejected,"Unsupported image span admitted");++guards;}
 // Actual selected-image observation is guarded only when a child needs it.
 for(uint32_t selected:{0u,0xb8e7u,0x1ffffeu,0x200000u,0x8ffffeu,0xbffffeu,0xffeffeu,0xffefffu,0xfff000u,0xfff400u,0xfff800u,0xffffffffu}){seed(first.get(),0,0x19000);T t({0x19000,ks::DspPort::A,0});Bus bus{first.get()};bool rejected=false,mutated=false;try{while(!t.complete()){if(const auto*q=t.task<ks::ParameterVoiceScaleTask>();q&&q->stage()==ks::ParameterVoiceScaleTask::Stage::ReadPatch){const auto slot=0x17560+20*q->slot();for(unsigned n=0;n<4;++n)first[slot+n]=uint8_t(selected>>(24-8*n));mutated=true;}bus.advance(t,t.nextClocks(bus.previous));}}catch(const std::logic_error&){rejected=true;}check(rejected&&mutated&&!bus.invalidAccess,"Bad live selected image admitted or dereferenced");++guards;}
 check(groups==0x7fff&&components==15,"Complete upload graph coverage missing");check(!allocations,"Pure graph allocated");std::cout<<"PASS: "<<calls<<" complete pure graphs / "<<phases<<" phases / "<<rejections<<" rejected budgets / "<<guards<<" guards; groups7fff/componentsf; allocations0\n";return 0;}catch(const std::exception&e){tracking=false;std::cerr<<e.what()<<'\n';return 1;}}
